def source(id, name, variant, parameters, purpose, description, strengths, repo, license, provenance, quants, caveat='', projector=None, family='', active=''):
    return {'id': id, 'name': name, 'variant': variant, 'parameters': parameters, 'purpose': purpose,
            'description': description, 'strengths': strengths, 'repo': repo, 'license': license,
            'provenance': provenance, 'quants': quants, 'caveat': caveat, 'projector': projector,
            'family': family or name.split(' ')[0], 'active_parameters': active}

def projector(repo, filename, note=''):
    return {'repo': repo, 'filename': filename, 'note': note}

